@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=Manrope:wght@400;500;600;700;800&display=swap');

:root {
  font-family: 'DM Sans', ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: #f5f2e9;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  --ink: #f5f2e9;
  --muted: #aaa99f;
  --panel: rgba(15, 26, 28, .82);
  --line: rgba(241, 238, 220, .14);
  --mint: #9ce0bf;
}

html, body { width: 100%; height: 100%; margin: 0; overflow: hidden; background: #10191a; }
* { box-sizing: border-box; }
button { font: inherit; }
canvas { position: fixed; inset: 0; width: 100%; height: 100%; display: block; }

#hud { position: fixed; z-index: 2; inset: 0; pointer-events: none; }
.topbar {
  position: absolute; top: 20px; left: 22px; right: 22px; height: 64px;
  display: flex; align-items: center; gap: 12px; padding: 0 17px;
  border: 1px solid var(--line); border-radius: 17px;
  background: linear-gradient(110deg, rgba(20, 32, 32, .88), rgba(27, 38, 37, .7));
  box-shadow: 0 12px 40px #101a1a28; backdrop-filter: blur(18px);
}
.brand-mark { display: grid; place-items: center; width: 36px; height: 36px; border-radius: 12px; background: #a4d5b9; color: #183229; font-family: Manrope, sans-serif; font-size: 19px; font-weight: 800; }
.brand-copy { min-width: 185px; }
#brand { color: #faf6e9; font-family: Manrope, sans-serif; font-weight: 800; font-size: 13px; letter-spacing: .15em; }
.eyebrow { color: #a8b0a7; font-size: 9px; font-weight: 700; letter-spacing: .14em; }
.brand-copy .eyebrow { margin-top: 3px; font-size: 8px; letter-spacing: .16em; }
.day-card, .clock-card { display: flex; flex-direction: column; justify-content: center; gap: 3px; height: 39px; padding-left: 17px; border-left: 1px solid var(--line); }
.day-card strong, .clock-card strong { color: #f6f1e4; font-family: Manrope, sans-serif; font-size: 13px; font-weight: 700; }
.clock-card { min-width: 100px; }
.money-card { display: flex; align-items: center; gap: 8px; margin-left: auto; padding: 9px 13px; border: 1px solid #d5c58b36; border-radius: 11px; background: #d5c58b12; color: #e7d59b; }
.money-card span { font-size: 13px; }
.money-card strong { font-family: Manrope, sans-serif; font-size: 14px; }

#needsPanel {
  position: absolute; top: 111px; left: 22px; width: 272px; padding: 17px 17px 15px;
  border: 1px solid var(--line); border-radius: 16px; background: var(--panel);
  box-shadow: 0 12px 35px #0a111133; backdrop-filter: blur(16px);
}
.panel-heading { display: flex; align-items: center; gap: 8px; margin-bottom: 15px; color: #c5c6b8; font-size: 9px; font-weight: 800; letter-spacing: .14em; }
.live-dot { width: 6px; height: 6px; border-radius: 50%; background: #a3d8b8; box-shadow: 0 0 9px #a3d8b8a0; }
.need-row { display: flex; align-items: center; gap: 10px; margin-top: 12px; }
.need-icon { display: grid; place-items: center; flex: 0 0 30px; height: 30px; border-radius: 10px; font-size: 17px; }
.energy-icon { color: #edc878; background: #edc87819; }
.hunger-icon { color: #e59b79; background: #e59b7919; }
.joy-icon { color: #9dd5b1; background: #9dd5b119; }
.need-info { flex: 1; min-width: 0; }
.need-label { display: flex; align-items: center; justify-content: space-between; margin-bottom: 6px; font-size: 11px; font-weight: 700; }
.need-hint { color: #888f85; font-size: 7px; font-weight: 700; letter-spacing: .09em; }
.bar-track { width: 100%; height: 5px; overflow: hidden; border-radius: 6px; background: #e6e2d71a; }
.need-fill { width: 100%; height: 100%; border-radius: inherit; transition: width .25s ease; }
.energy-fill { background: linear-gradient(90deg, #c99f50, #f3d889); box-shadow: 0 0 10px #e9c66c50; }
.hunger-fill { background: linear-gradient(90deg, #c77b63, #edae8b); box-shadow: 0 0 10px #e9987850; }
.joy-fill { background: linear-gradient(90deg, #70b58e, #a5e0bb); box-shadow: 0 0 10px #90d5a550; }
#status { position: absolute; bottom: 27px; left: 50%; transform: translateX(-50%); max-width: min(560px, calc(100vw - 32px)); padding: 11px 18px; border: 1px solid #eee8d126; border-radius: 999px; background: rgba(19, 30, 29, .75); color: #f3f0e5; text-align: center; font-size: 12px; font-weight: 600; box-shadow: 0 6px 25px #0c15152a; backdrop-filter: blur(12px); }
.look-hint { position: absolute; right: 30px; bottom: 31px; display: flex; align-items: center; gap: 7px; color: #e6e3d2c4; font-size: 8px; font-weight: 800; letter-spacing: .14em; text-shadow: 0 1px 5px #14211f; }
.look-dot { width: 6px; height: 6px; border: 1px solid #e6e3d2; border-radius: 50%; }

#touchControls { display: none; }
#touchControls button { border: 1px solid #e7ead05c; color: #f7f3e8; background: #192624d9; font: inherit; font-weight: 800; touch-action: none; user-select: none; -webkit-user-select: none; backdrop-filter: blur(10px); }
#overlay { position: fixed; z-index: 4; inset: 0; display: grid; place-items: center; padding: 20px; background: linear-gradient(100deg, #0d1712aa 0%, #111e1b62 55%, #101a1970 100%); opacity: 0; visibility: hidden; transition: opacity .25s, visibility .25s; }
#overlay.visible { opacity: 1; visibility: visible; }
.panel { width: min(500px, calc(100vw - 36px)); margin-right: auto; margin-left: clamp(20px, 8vw, 130px); padding: 37px 38px 27px; border: 1px solid #eee9d42e; border-radius: 23px; background: linear-gradient(145deg, rgba(27, 40, 35, .95), rgba(18, 30, 27, .93)); box-shadow: 0 25px 90px #070d0b72, 0 0 60px #c7d7a410; backdrop-filter: blur(20px); }
.panel-kicker { display: flex; align-items: center; gap: 9px; margin-bottom: 21px; color: #a8d7b5; font-size: 9px; font-weight: 800; letter-spacing: .18em; }
.panel-kicker span { width: 7px; height: 7px; border-radius: 50%; background: #a3d9b2; box-shadow: 0 0 10px #a3d9b2; }
.panel h1 { margin: 0 0 16px; color: #f5f1e6; font-family: Manrope, sans-serif; font-size: clamp(38px, 6vw, 57px); font-weight: 600; letter-spacing: -.065em; line-height: 1.03; }
.panel h1 em { color: #acd8b6; font-style: normal; }
.panel p { max-width: 395px; margin: 0 0 23px; color: #bbc4b9; line-height: 1.65; font-size: 13px; }
.panel-controls { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 24px; }
.panel-controls span { padding: 7px 9px; border: 1px solid #e8ebd51c; border-radius: 7px; color: #9ca89c; font-size: 8px; font-weight: 700; letter-spacing: .08em; }
.panel-controls b { margin-right: 5px; color: #ececdd; font-size: 9px; }
.panel button { display: flex; align-items: center; justify-content: space-between; width: 100%; padding: 14px 17px; border: 0; border-radius: 11px; color: #1d3028; background: linear-gradient(100deg, #aadbb6, #c3dfb2); font: inherit; font-size: 12px; font-weight: 800; cursor: pointer; box-shadow: 0 8px 26px #96cca72b; transition: transform .18s, filter .18s; }
.panel button span { font-size: 18px; line-height: 10px; }
.panel button:hover { filter: brightness(1.08); transform: translateY(-1px); }
.panel-footnote { margin-top: 18px; color: #7e8d80; text-align: center; font-size: 8px; font-weight: 700; letter-spacing: .14em; }

@media (max-width: 800px), (pointer: coarse) {
