106:         const windowZ = windowCenters[index];
107:         const windowY = floor * floorHeight + 1.85;
108:         if (floor === 0 && Math.abs(windowZ - z) < 1.1) continue; // keep the front door clear
109:         const frameX = front - side * 0.12;
110:         const width = 1.42;
111:         const frame = trimMat;
112:         box(0.16, 1.35, 0.12, frame, frameX, windowY, windowZ - width / 2, false);
113:         box(0.16, 1.35, 0.12, frame, frameX, windowY, windowZ + width / 2, false);
