141:     buildingAccess.push({
142:       id: `${side < 0 ? 'west' : 'east'}-${row + 1}`,
143:       name: `${name} ${String(row + 1).padStart(2, '0')}`,
144:       side, x, z, front, floors, floorHeight, doorZ: z,
