458: function inRoom(zone) {
459:   const dx = Math.abs(camera.position.x - zone.center.x);
460:   const dy = Math.abs(camera.position.y - zone.center.y);
461:   const dz = Math.abs(camera.position.z - zone.center.z);
462:   return dx <= zone.size.x / 2 && dy <= zone.size.y / 2 && dz <= zone.size.z / 2;
463: }
