474: function interact() {
475:   if (!state.started || state.mapOpen || state.interactCooldown > 0) {
476:     return;
477:   }
478: 
479:   const current = currentRoom();
480:   const closest = nearestNode();
481:   const targetNode = current ? lifeNodes.find((node) => node.key === current.key) : closest?.node;
482: 
483:   if (!targetNode || (closest && closest.distance > 4.5 && !current)) {
484:     setStatus('Move inside a building or room to interact.');
485:     return;
486:   }
487: 
488:   state.interactCooldown = 0.45;
489: 
490:   switch (targetNode.key) {
491:     case 'home':
492:       if (state.time < 21 && state.time > 6) {
493:         state.energy = clamp(state.energy + 36, 0, 100);
494:         state.hunger = clamp(state.hunger - 10, 0, 100);
495:         state.joy = clamp(state.joy + 12, 0, 100);
496:         setStatus('You rest at home and recover your energy.');
497:       } else {
498:         setStatus('Home is cozy, but the city is still active.');
499:       }
500:       break;
501:     case 'work':
502:       if (state.time >= 9 && state.time <= 18) {
503:         state.money += 30;
504:         state.energy = clamp(state.energy - 18, 0, 100);
505:         state.hunger = clamp(state.hunger - 12, 0, 100);
506:         state.joy = clamp(state.joy - 8, 0, 100);
507:         setStatus('A productive shift. The bank account is healthier.');
508:       } else {
509:         setStatus('The office is off-hours right now.');
510:       }
511:       break;
512:     case 'cafe':
513:       if (state.money >= 10) {
514:         state.hunger = clamp(state.hunger + 28, 0, 100);
515:         state.energy = clamp(state.energy + 8, 0, 100);
516:         state.joy = clamp(state.joy + 8, 0, 100);
517:         state.money -= 10;
518:         setStatus('Fresh food and coffee keep you going.');
519:       } else {
520:         setStatus('You need $10 for a meal at the cafe.');
521:       }
522:       break;
523:     case 'park':
524:       state.joy = clamp(state.joy + 26, 0, 100);
525:       state.energy = clamp(state.energy + 8, 0, 100);
526:       state.hunger = clamp(state.hunger - 8, 0, 100);
527:       setStatus('A walk in the park lifts your mood.');
528:       break;
529:     case 'club':
530:       if (state.money >= 12) {
531:         state.money -= 12;
532:         state.joy = clamp(state.joy + 30, 0, 100);
533:         state.energy = clamp(state.energy - 12, 0, 100);
534:         setStatus('Late-night music and conversation energize you.');
535:       } else {
536:         setStatus('You need a little cash before hitting the club.');
537:       }
538:       break;
539:     default:
540:       break;
